args.ReplacementContent:
for await (const line of rl) {
  if (line.toLowerCase().includes('index.html')) {
    try {
      const obj = JSON.parse(line);
      console.log(`Match at Step: ${obj.step_index} | Type: ${obj.type}`);
      if (obj.tool_calls) {
        obj.tool_calls.forEach((tc, idx) => {
          console.log(`  Tool: ${tc.name} | Target: ${tc.arguments?.TargetFile || tc.arguments?.AbsolutePath}`);
          fs.writeFileSync(`scratch/index_match_${obj.step_index}_${idx}.json`, JSON.stringify(tc, null, 2), 'utf8');
        });
      }
    } catch (err) {
      // ignore
    }
  }
}

args.TargetContent:
for await (const line of rl) {
  if (line.toLowerCase().includes('index.html') && line.includes('replace_file_content')) {
    try {
      const obj = JSON.parse(line);
      if (obj.tool_calls) {
        obj.tool_calls.forEach((tc, idx) => {
          if (tc.name === 'replace_file_content' && tc.arguments && tc.arguments.TargetFile.includes('index.html')) {
            console.log(`\n--- STEP ${obj.step_index} (${tc.name}) ---`);
            console.log('Instruction:', tc.arguments.Instruction);
            console.log('TargetContent Length:', tc.arguments.TargetContent?.length);
            console.log('ReplacementContent Length:', tc.arguments.ReplacementContent?.length);
            fs.writeFileSync(`scratch/index_patch_${obj.step_index}_${idx}.txt`, tc.arguments.ReplacementContent || '', 'utf8');
            console.log(`Saved ReplacementContent to scratch/index_patch_${obj.step_index}_${idx}.txt`);
          }
        });
      }
    } catch (err) {
      // ignore
    }
  }
}
